import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Watchdog, health and klog from apps","description":"","frontmatter":{},"headers":[],"relativePath":"l1/watchdog-health.md","filePath":"l1/watchdog-health.md"}'),l={name:"l1/watchdog-health.md"};function h(c,e,d,i,r,n){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="watchdog-health-and-klog-from-apps" tabindex="-1">Watchdog, health and klog from apps <a class="header-anchor" href="#watchdog-health-and-klog-from-apps" aria-label="Permalink to &quot;Watchdog, health and klog from apps&quot;">​</a></h1><h2 id="watchdog-service-watchdog-l1svc-cat-11" tabindex="-1">Watchdog (service <code>watchdog</code>, L1SVC cat 11) <a class="header-anchor" href="#watchdog-service-watchdog-l1svc-cat-11" aria-label="Permalink to &quot;Watchdog (service `watchdog`, L1SVC cat 11)&quot;">​</a></h2><p>A registered slot is a <em>policy</em> watchdog: the owning task must feed it; a timeout kills the task (reason logged) while the kernel lives. Hardware watchdogs (Intel TCO, ACPI WDAT) are layered underneath and reset the whole machine - the E2E suite proves both with real resets and second boots.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>watchdog_register(name, timeout_ms, policy)  -&gt; slot</span></span>\n<span class="line"><span>watchdog_start / feed / stop / set_timeout</span></span></code></pre></div><p><code>ush&gt; watchdog</code> (or the sysdiag classic table) reports slots and policies; the starve test (<code>wd-starve</code>, 3000 ms) is how the E2E proves the kill path.</p><h2 id="health-service-health-l1svc-cat-9" tabindex="-1">Health (service <code>health</code>, L1SVC cat 9) <a class="header-anchor" href="#health-service-health-l1svc-cat-9" aria-label="Permalink to &quot;Health (service `health`, L1SVC cat 9)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>health_get_cpu / mem / tasks / io      (the snapshot sources)</span></span>\n<span class="line"><span>health_export(path)                    (valid JSON)</span></span></code></pre></div><p>Thresholds raise alarms into the kernel log (<code>CPU-LOCKED</code> on a pinned core, ...). The app surface: <code>health</code> (snapshot - the sysdiag wizard&#39;s first menu item), <code>health watch</code> (live monitor, ENTER exits), <code>health export [path]</code>.</p><h2 id="klog-service-klog-l1svc-cat-10" tabindex="-1">klog (service <code>klog</code>, L1SVC cat 10) <a class="header-anchor" href="#klog-service-klog-l1svc-cat-10" aria-label="Permalink to &quot;klog (service `klog`, L1SVC cat 10)&quot;">​</a></h2><p><code>dmesg [N]</code> (the ring, newest last), <code>logcat</code> (structured: -l level -m module -k key -t seconds -n N -f follow), <code>logctl status|level|...</code> (runtime control). The sysdiag log-tools submenu fronts all three.</p><h2 id="the-mega-app-view" tabindex="-1">The mega-app view <a class="header-anchor" href="#the-mega-app-view" aria-label="Permalink to &quot;The mega-app view&quot;">​</a></h2><p><code>sysdiag</code> groups the whole observability story: health snapshot, kernel log, memory picture, scheduler stats, crash records, log tools, selftest lab. Watchdog + health + klog stay individually reachable (classic/direct) for scripts and the E2E suites.</p>',12)])])}const m=a(l,[["render",h]]);export{g as __pageData,m as default};
